667	/*
668	 * Finds the point of intersection p between two closed segments ab and cd.
669	 *
670	 * Returns p and a char with the following meaning:
671	 *
672	 *   COLINEAR_SEGMENTS: The segments colinearly overlap, sharing a point.
673	 *
674	 *   ENDPOINT_ONLY:     An endpoint (vertex) of one segment is on the other
675	 *                      segment, but COLINEAR_SEGMENTS doesn't hold.
676	 *
677	 *   NORMAL_INTERSECT:  The segments intersect properly (i.e., they share
678	 *                      a point and neither ENDPOINT_ONLY nor
679	 *                      COLINEAR_SEGMENTS holds).
680	 *
681	 *   NO_INTERSECTION:   The segments do not intersect (i.e., they share
682	 *                      no points).
683	 *
684	 * Note that two colinear segments that share just one point, an endpoint
685	 * of each, returns COLINEAR_SEGMENTS rather than ENDPOINT_ONLY as one
686	 * might expect.
687	 */
688	int SegSegIntersect(Vec *pEdge, Vec *qEdge, Vec *p0, Vec *p1, Vec *q0, Vec *q1,
689	                    Vec *intersect1, Vec *intersect2) {
690	  double pDot, qDot;   // Dot product [cos(length)] of the edge vertices
691	  double p0Dot, p1Dot;  // Dot product from vertices to intersection
692	  double q0Dot, q1Dot;  // Dot pro}duct from vertices to intersection
693	  int len;
694	
695	  // Get the edge lengths (actually cos(length))
696	
697	  pDot = Dot(p0, p1);
698	  qDot = Dot(q0, q1);
699	
700	  // Find the point of intersection
701	
702	  len = Cross(pEdge, qEdge, intersect1);
703	
704	  // If the two edges are colinear, check to see if they overlap
705	
706	  if (len == 0) {
707	    if (Between(q0, p0, p1) && Between(q1, p0, p1)) {
708	      *intersect1 = *q0;
709	      *intersect2 = *q1;
710	      return COLINEAR_SEGMENTS;
711	    }
712	
713	    if (Between(p0, q0, q1) && Between(p1, q0, q1)) {
714	      *intersect1 = *p0;
715	      *intersect2 = *p1;
716	      return COLINEAR_SEGMENTS;
717	    }
718	
719	    if (Between(q0, p0, p1) && Between(p1, q0, q1)) {
720	      *intersect1 = *q0;
721	      *intersect2 = *p1;
722	      return COLINEAR_SEGMENTS;
723	    }
724	
725	    if (Between(p0, q0, q1) && Between(q1, p0, p1)) {
726	      *intersect1 = *p0;
727	      *intersect2 = *q1;
728	      return COLINEAR_SEGMENTS;
729	    }
730	
731	    if (Between(q1, p0, p1) && Between(p1, q0, q1)) {
732	      *intersect1 = *p0;
733	      *intersect2 = *p1;
734	      return COLINEAR_SEGMENTS;
735	    }
736	
737	    if (Between(q0, p0, p1) && Between(p0, q0, q1)) {
738	      *intersect1 = *p0;
739	      *intersect2 = *q0;
740	      return COLINEAR_SEGMENTS;
741	    }
742	
743	    return NO_INTERSECTION;
744	  }
745	
746	  // If this is the wrong one of the two
747	  // (other side of the sky) reverse it
748	
749	  Normalize(intersect1);
750	
751	  if (Dot(intersect1, p0) < 0.)
752	    Reverse(intersect1);
753	
754	  // Point has to be inside both sides to be an intersection
755	
756	  if ((p0Dot = Dot(intersect1, p0)) < pDot)
757	    return NO_INTERSECTION;
758	  if ((p1Dot = Dot(intersect1, p1)) < pDot)
759	    return NO_INTERSECTION;
760	  if ((q0Dot = Dot(intersect1, q0)) < qDot)
761	    return NO_INTERSECTION;
762	  if ((q1Dot = Dot(intersect1, q1)) < qDot)
763	    return NO_INTERSECTION;
764	
765	  // Otherwise, if the intersection is at an endpoint
766	
767	  if (p0Dot == pDot)
768	    return ENDPOINT_ONLY;
769	  if (p1Dot == pDot)
770	    return ENDPOINT_ONLY;
771	  if (q0Dot == qDot)
772	    return ENDPOINT_ONLY;
773	  if (q1Dot == qDot)
774	    return ENDPOINT_ONLY;
775	
776	  // Otherwise, it is a normal intersection
777	
778	  return NORMAL_INTERSECT;
779	}
