    }

    if (Between(p0, q0, q1, tol) && Between(p1, q0, q1, tol)) {
      *intersect1 = *p0;
      *intersect2 = *p1;
      return COLINEAR_SEGMENTS;
    }

    if (Between(q0, p0, p1, tol) && Between(p1, q0, q1, tol)) {
      *intersect1 = *q0;
      *intersect2 = *p1;
      return COLINEAR_SEGMENTS;
    }

    if (Between(p0, q0, q1, tol) && Between(q1, p0, p1, tol)) {
      *intersect1 = *p0;
      *intersect2 = *q1;
      return COLINEAR_SEGMENTS;
    }

    if (Between(q1, p0, p1, tol) && Between(p1, q0, q1, tol)) {
      *intersect1 = *p0;
      *intersect2 = *p1;
      return COLINEAR_SEGMENTS;
    }

    if (Between(q0, p0, p1, tol) && Between(p0, q0, q1, tol)) {
      *intersect1 = *p0;
      *intersect2 = *q0;
      return COLINEAR_SEGMENTS;
    }

    return NO_INTERSECTION;
  }

  // If this is the wrong one of the two
  // (other side of the sky) reverse it

  Normalize(intersect1);

  if (Dot(intersect1, p0) < 0.)
    Reverse(intersect1);

  // Point has to be inside both sides to be an intersection.
  //
  // The original test compared cosines of the angular distances from the
  // intersection candidate to the segment endpoints with the cosine of the
